BEGIN;
CREATE TABLE tenants(id text PRIMARY KEY,slug text UNIQUE NOT NULL,name text NOT NULL,monthly_event_limit integer NOT NULL CHECK(monthly_event_limit BETWEEN 1 AND 1000000),used_events integer NOT NULL DEFAULT 0 CHECK(used_events>=0),status text NOT NULL CHECK(status IN('active','suspended','closed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),key_hash text UNIQUE NOT NULL,scopes text[] NOT NULL,revoked_at timestamptz);
CREATE TABLE event_inbox(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),producer_source text NOT NULL,producer_event_id text NOT NULL,event_type text NOT NULL,subject text NOT NULL,sequence bigint NOT NULL CHECK(sequence>0),payload jsonb NOT NULL,fingerprint text NOT NULL,status text NOT NULL CHECK(status IN('accepted','quarantined')),received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,producer_source,producer_event_id));
CREATE TABLE aggregate_sequences(tenant_id text NOT NULL REFERENCES tenants(id),producer_source text NOT NULL,subject text NOT NULL,last_sequence bigint NOT NULL CHECK(last_sequence>=0),PRIMARY KEY(tenant_id,producer_source,subject));
CREATE TABLE subscriptions(id bigserial PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),event_type text NOT NULL,workflow_id text NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,event_type,workflow_id));
CREATE TABLE deliveries(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),event_id text NOT NULL REFERENCES event_inbox(id),workflow_id text NOT NULL,status text NOT NULL CHECK(status IN('queued','retry_scheduled','succeeded','dead_lettered')),attempt integer NOT NULL DEFAULT 0 CHECK(attempt BETWEEN 0 AND 3),next_attempt_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE event_outbox(id bigserial PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),delivery_id text NOT NULL REFERENCES deliveries(id),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dead_letters(id bigserial PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),delivery_id text NOT NULL REFERENCES deliveries(id),error_code text NOT NULL,replay_authorized boolean NOT NULL DEFAULT false,approved_by text,approval_reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quarantine(id bigserial PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),event_id text NOT NULL REFERENCES event_inbox(id),reason text NOT NULL,replay_authorized boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id),event_type text NOT NULL,payload jsonb NOT NULL,actor_id text NOT NULL,event_time timestamptz NOT NULL,previous_hash text NOT NULL,event_hash text NOT NULL,PRIMARY KEY(tenant_id,id));
ALTER TABLE api_keys ENABLE ROW LEVEL SECURITY;ALTER TABLE api_keys FORCE ROW LEVEL SECURITY;ALTER TABLE event_inbox ENABLE ROW LEVEL SECURITY;ALTER TABLE event_inbox FORCE ROW LEVEL SECURITY;ALTER TABLE aggregate_sequences ENABLE ROW LEVEL SECURITY;ALTER TABLE aggregate_sequences FORCE ROW LEVEL SECURITY;ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;ALTER TABLE subscriptions FORCE ROW LEVEL SECURITY;ALTER TABLE deliveries ENABLE ROW LEVEL SECURITY;ALTER TABLE deliveries FORCE ROW LEVEL SECURITY;ALTER TABLE event_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE event_outbox FORCE ROW LEVEL SECURITY;ALTER TABLE dead_letters ENABLE ROW LEVEL SECURITY;ALTER TABLE dead_letters FORCE ROW LEVEL SECURITY;ALTER TABLE quarantine ENABLE ROW LEVEL SECURITY;ALTER TABLE quarantine FORCE ROW LEVEL SECURITY;ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;ALTER TABLE audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY api_keys_tenant ON api_keys USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE POLICY inbox_tenant ON event_inbox USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE POLICY sequences_tenant ON aggregate_sequences USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE POLICY subscriptions_tenant ON subscriptions USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE POLICY deliveries_tenant ON deliveries USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE POLICY outbox_tenant ON event_outbox USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE POLICY dlq_tenant ON dead_letters USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE POLICY quarantine_tenant ON quarantine USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE POLICY audit_tenant ON audit_events USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
COMMIT;
